        console.error("\n   → The requested setting was not found");
      }
    } else if (error instanceof Error) {
      console.error("\n❌ Unexpected Error:");
      console.error(`   ${error.message}`);
    } else {
      console.error("\n❌ Unknown error occurred:", error);
    }
    process.exit(1);
  }
}

