### 5) Common pitfalls + error handling

```ts
import {
  ManagedIdentityCredential,
  CredentialUnavailableError
} from "@azure/identity";

const credential = new ManagedIdentityCredential(
  process.env.AZURE_USER_ASSIGNED_CLIENT_ID
);

async function safeCall() {
