 * Complete Production-Ready Example
 * 
 * This example demonstrates a full application using managed identity
 * with proper error handling, fallback strategies, and best practices.
 */

import {
  ManagedIdentityCredential,
  DefaultAzureCredential,
  ChainedTokenCredential,
  AzureCliCredential,
  TokenCredential
} from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";
import { CosmosClient } from "@azure/cosmos";

// Configuration interface
interface AppConfig {
  environment: "development" | "staging" | "production";
  managedIdentityClientId?: string;
  keyVaultUrl: string;
  storageAccountUrl: string;
  cosmosEndpoint: string;
}

// Credential factory with intelligent fallback
class CredentialFactory {
  static create(config: AppConfig): TokenCredential {
    const isDevelopment = config.environment === "development";
    const isAzureEnvironment = process.env.WEBSITE_INSTANCE_ID !== undefined ||
                               process.env.MSI_ENDPOINT !== undefined;

    if (isDevelopment && !isAzureEnvironment) {
      console.log("🔧 Development mode: Using Azure CLI credential");
      return new ChainedTokenCredential(
        new AzureCliCredential(),
        new DefaultAzureCredential()
      );
    }

    if (config.managedIdentityClientId) {
      console.log(`🔐 Using user-assigned managed identity: ${config.managedIdentityClientId}`);
      return new ChainedTokenCredential(
        new ManagedIdentityCredential(config.managedIdentityClientId),
        new AzureCliCredential() // Fallback for local testing with service principal
      );
    }

    console.log("🔐 Using system-assigned managed identity");
    return new ManagedIdentityCredential();
  }
}

// Azure Services wrapper with managed identity
class AzureServices {
  private credential: TokenCredential;
  private config: AppConfig;
  private secretClient?: SecretClient;
  private blobServiceClient?: BlobServiceClient;
  private cosmosClient?: CosmosClient;

  constructor(config: AppConfig) {
    this.config = config;
    this.credential = CredentialFactory.create(config);
  }

  // Initialize and validate managed identity
  async initialize(): Promise<void> {
    console.log("Initializing Azure services...");

    try {
      // Test credential by acquiring a token
      const token = await this.credential.getToken("https://vault.azure.net/.default");
      console.log("✓ Managed identity validated");
      console.log(`  Token expires: ${new Date(token.expiresOnTimestamp).toISOString()}`);

      // Initialize clients
      this.secretClient = new SecretClient(this.config.keyVaultUrl, this.credential);
      this.blobServiceClient = new BlobServiceClient(
        this.config.storageAccountUrl,
        this.credential
      );
      this.cosmosClient = new CosmosClient({
        endpoint: this.config.cosmosEndpoint,
        aadCredentials: this.credential
      });

      console.log("✓ Azure services initialized successfully");
    } catch (error: any) {
      console.error("❌ Failed to initialize Azure services");
      this.handleCredentialError(error);
      throw error;
    }
  }

  // Key Vault operations
  async getSecret(secretName: string): Promise<string> {
    if (!this.secretClient) {
      throw new Error("Services not initialized. Call initialize() first.");
    }

    try {
      const secret = await this.secretClient.getSecret(secretName);
      return secret.value || "";
    } catch (error: any) {
      console.error(`Error retrieving secret '${secretName}':`, error.message);

      if (error.statusCode === 403) {
        console.error(`
Missing Key Vault permission. Grant access with:
az keyvault set-policy --name <vault-name> --object-id <identity-object-id> --secret-permissions get

Or using RBAC:
az role assignment create --assignee <identity-object-id> --role "Key Vault Secrets User" --scope <vault-resource-id>
        `);
      }

      throw error;
    }
  }

  async setSecret(secretName: string, value: string): Promise<void> {
    if (!this.secretClient) {
      throw new Error("Services not initialized. Call initialize() first.");
    }

    try {
      await this.secretClient.setSecret(secretName, value);
      console.log(`✓ Secret '${secretName}' updated successfully`);
    } catch (error: any) {
      if (error.statusCode === 403) {
        console.error("Missing Key Vault 'set' permission");
      }
      throw error;
    }
  }

  // Blob Storage operations
  async uploadBlob(containerName: string, blobName: string, content: string): Promise<void> {
    if (!this.blobServiceClient) {
      throw new Error("Services not initialized. Call initialize() first.");
    }

    try {
      const containerClient = this.blobServiceClient.getContainerClient(containerName);

      // Create container if it doesn't exist
      await containerClient.createIfNotExists();

      const blockBlobClient = containerClient.getBlockBlobClient(blobName);
      await blockBlobClient.upload(content, content.length);

      console.log(`✓ Blob '${blobName}' uploaded to container '${containerName}'`);
    } catch (error: any) {
      console.error(`Error uploading blob:`, error.message);

      if (error.statusCode === 403) {
        console.error(`
Missing Storage permission. Grant access with:
az role assignment create --assignee <identity-object-id> --role "Storage Blob Data Contributor" --scope <storage-account-resource-id>
        `);
      }

      throw error;
    }
  }

  async downloadBlob(containerName: string, blobName: string): Promise<string> {
    if (!this.blobServiceClient) {
      throw new Error("Services not initialized. Call initialize() first.");
    }

    try {
      const containerClient = this.blobServiceClient.getContainerClient(containerName);
      const blobClient = containerClient.getBlobClient(blobName);

      const downloadResponse = await blobClient.download();
      const downloaded = await this.streamToString(downloadResponse.readableStreamBody!);

      return downloaded;
    } catch (error: any) {
      console.error(`Error downloading blob:`, error.message);
      throw error;
    }
  }

  // Cosmos DB operations
  async queryDocuments(databaseId: string, containerId: string, query: string): Promise<any[]> {
    if (!this.cosmosClient) {
      throw new Error("Services not initialized. Call initialize() first.");
    }

    try {
      const database = this.cosmosClient.database(databaseId);
      const container = database.container(containerId);

      const { resources } = await container.items.query(query).fetchAll();
      return resources;
    } catch (error: any) {
      console.error(`Error querying Cosmos DB:`, error.message);

      if (error.code === 403) {
        console.error(`
Missing Cosmos DB permission. Grant access with:
az cosmosdb sql role assignment create --account-name <account> --resource-group <rg> --role-definition-name "Cosmos DB Built-in Data Contributor" --principal-id <identity-object-id> --scope "/"
        `);
      }

      throw error;
    }
  }

  // Error handling helper
  private handleCredentialError(error: any): void {
    if (error.message?.includes("ManagedIdentityCredential")) {
      console.error(`
⚠️  MANAGED IDENTITY NOT AVAILABLE

Possible causes:
1. Not running on an Azure resource that supports managed identity
2. Managed identity not enabled on the resource
3. User-assigned identity not attached to the resource

Fixes:
- Enable system-assigned identity: Azure Portal → Resource → Identity → System assigned: ON
- Attach user-assigned identity: Azure Portal → Resource → Identity → User assigned → Add
- For local development: az login
      `);
    } else if (error.code === "ECONNREFUSED" || error.message?.includes("IMDS")) {
      console.error(`
⚠️  INSTANCE METADATA SERVICE (IMDS) UNREACHABLE

This typically means:
1. Not running on an Azure VM/App Service/Function/Container
2. Network firewall blocking IMDS endpoint (169.254.169.254)
3. Running in a restricted network environment

For local development, make sure you're logged in:
az login
az account set --subscription "<your-subscription>"
      `);
    }
  }

  // Helper: Convert stream to string
  private async streamToString(readableStream: NodeJS.ReadableStream): Promise<string> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      readableStream.on("data", (data) => {
        chunks.push(data instanceof Buffer ? data : Buffer.from(data));
      });
      readableStream.on("end", () => {
        resolve(Buffer.concat(chunks).toString("utf8"));
      });
      readableStream.on("error", reject);
    });
  }
}

// Example application
async function main() {
  // Load configuration
  const config: AppConfig = {
    environment: (process.env.NODE_ENV as any) || "development",
    managedIdentityClientId: process.env.MANAGED_IDENTITY_CLIENT_ID,
    keyVaultUrl: process.env.KEY_VAULT_URL || "https://my-vault.vault.azure.net",
    storageAccountUrl: process.env.STORAGE_ACCOUNT_URL || "https://mystorage.blob.core.windows.net",
    cosmosEndpoint: process.env.COSMOS_ENDPOINT || "https://mycosmosdb.documents.azure.com:443/"
  };

  console.log("=== Azure Managed Identity Demo ===");
  console.log(`Environment: ${config.environment}`);
  console.log(`User-assigned identity: ${config.managedIdentityClientId || "None (using system-assigned)"}`);
  console.log();

  try {
    // Initialize services
    const services = new AzureServices(config);
    await services.initialize();

    // Example 1: Work with Key Vault
    console.log("\n--- Key Vault Operations ---");
    const dbPassword = await services.getSecret("database-password");
    console.log(`✓ Retrieved database password (length: ${dbPassword.length})`);

    // Example 2: Work with Blob Storage
    console.log("\n--- Blob Storage Operations ---");
    await services.uploadBlob("logs", "app.log", `Log entry at ${new Date().toISOString()}`);
    const logContent = await services.downloadBlob("logs", "app.log");
    console.log(`✓ Downloaded log: ${logContent}`);

    // Example 3: Work with Cosmos DB
    console.log("\n--- Cosmos DB Operations ---");
    const documents = await services.queryDocuments(
      "my-database",
      "my-container",
      "SELECT * FROM c WHERE c.status = 'active' OFFSET 0 LIMIT 10"
    );
    console.log(`✓ Found ${documents.length} active documents`);

    console.log("\n✓ All operations completed successfully!");

  } catch (error: any) {
    console.error("\n❌ Application error:", error.message);
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main().catch(console.error);
}

export { AzureServices, CredentialFactory, AppConfig };
