 * System-Assigned vs User-Assigned Managed Identity
 * Comparison, Best Practices, and Decision Guide
 */

import { ManagedIdentityCredential, DefaultAzureCredential } from "@azure/identity";

// ============================================================================
// COMPARISON: SYSTEM-ASSIGNED VS USER-ASSIGNED
// ============================================================================

/**
 * SYSTEM-ASSIGNED MANAGED IDENTITY
 * 
 * Pros:
 * - Simpler to set up (no need to specify identity)
 * - Automatically created with the resource
 * - Automatically deleted when resource is deleted
 * - No separate Azure resource to manage
 * - Perfect for 1:1 resource-to-identity relationships
 * 
 * Cons:
 * - Tied to the lifecycle of a single resource
 * - Cannot be shared across multiple resources
 * - Loses all permissions when resource is deleted
 * - Harder to pre-configure permissions before resource creation
 * - Cannot be created separately from the resource
 * 
 * Use When:
 * - Single Azure resource needs its own identity
 * - Identity permissions are specific to that resource
 * - Resource lifecycle matches identity lifecycle
 * - Simplicity is preferred over flexibility
 */
function createSystemAssignedExample() {
  // No parameters needed - uses the identity attached to the resource
  return new ManagedIdentityCredential();
}

/**
 * USER-ASSIGNED MANAGED IDENTITY
 * 
 * Pros:
 * - Can be shared across multiple resources
 * - Independent lifecycle (survives resource deletion)
 * - Can be pre-created with permissions before assigning to resources
 * - Better for multi-resource scenarios
 * - Easier to rotate or update permissions centrally
 * - Can be used in disaster recovery scenarios
 * 
 * Cons:
 * - Requires explicit client ID specification
 * - Additional Azure resource to manage
 * - Must be explicitly assigned to resources
 * - Slightly more complex configuration
 * 
 * Use When:
 * - Multiple resources need the same identity
 * - Identity should persist beyond resource lifecycle
 * - Need to pre-configure permissions before resource creation
 * - Want to centrally manage identity permissions
 * - Implementing blue/green deployments
 */
function createUserAssignedExample(clientId: string) {
  return new ManagedIdentityCredential({ clientId });
}

// ============================================================================
// DECISION MATRIX
// ============================================================================

interface IdentityRequirements {
  multipleResources: boolean;
  persistBeyondResourceDeletion: boolean;
  preConfigurePermissions: boolean;
  simplicity: boolean;
  blueGreenDeployment: boolean;
}

function recommendIdentityType(requirements: IdentityRequirements): string {
  // User-assigned if any of these are true
  if (
    requirements.multipleResources ||
    requirements.persistBeyondResourceDeletion ||
    requirements.preConfigurePermissions ||
    requirements.blueGreenDeployment
  ) {
    return "user-assigned";
  }

  // System-assigned for simplicity
  if (requirements.simplicity) {
    return "system-assigned";
  }

  // Default to system-assigned for single-resource scenarios
  return "system-assigned";
}

// Example usage
const recommendation1 = recommendIdentityType({
  multipleResources: false,
  persistBeyondResourceDeletion: false,
  preConfigurePermissions: false,
  simplicity: true,
  blueGreenDeployment: false
});
console.log("Recommendation:", recommendation1); // "system-assigned"

const recommendation2 = recommendIdentityType({
  multipleResources: true,
  persistBeyondResourceDeletion: true,
  preConfigurePermissions: true,
  simplicity: false,
  blueGreenDeployment: true
});
console.log("Recommendation:", recommendation2); // "user-assigned"

// ============================================================================
// BEST PRACTICES
// ============================================================================

/**
 * BEST PRACTICE #1: Use DefaultAzureCredential for maximum flexibility
 * Works both in Azure and local development
 */
function bestPracticeDefaultCredential() {
  // Works with both system-assigned and user-assigned identities
  // Falls back to Azure CLI for local development
  const credential = new DefaultAzureCredential({
    // Optional: Specify client ID if using user-assigned identity
    managedIdentityClientId: process.env.MANAGED_IDENTITY_CLIENT_ID
  });

  return credential;
}

/**
 * BEST PRACTICE #2: Store configuration in environment variables
 */
const MANAGED_IDENTITY_CONFIG = {
  // Type of identity
  type: process.env.MANAGED_IDENTITY_TYPE || "system-assigned",

  // Client ID for user-assigned identity
  clientId: process.env.MANAGED_IDENTITY_CLIENT_ID,

  // Resource ID for user-assigned identity (alternative)
  resourceId: process.env.MANAGED_IDENTITY_RESOURCE_ID
} as const;

/**
 * BEST PRACTICE #3: Create a credential factory function
 */
function createCredential() {
  if (MANAGED_IDENTITY_CONFIG.type === "user-assigned") {
    if (MANAGED_IDENTITY_CONFIG.clientId) {
      return new ManagedIdentityCredential({
        clientId: MANAGED_IDENTITY_CONFIG.clientId
      });
    }
    if (MANAGED_IDENTITY_CONFIG.resourceId) {
      return new ManagedIdentityCredential({
        resourceId: MANAGED_IDENTITY_CONFIG.resourceId
      });
    }
    throw new Error(
      "User-assigned identity requires MANAGED_IDENTITY_CLIENT_ID or MANAGED_IDENTITY_RESOURCE_ID"
    );
  }

  // Default to system-assigned
  return new ManagedIdentityCredential();
}

/**
 * BEST PRACTICE #4: Implement proper error handling
 */
async function properErrorHandling() {
  const credential = createCredential();

  try {
    const token = await credential.getToken("https://management.azure.com/.default");
    return token;
  } catch (error: any) {
    // Log detailed error information
    console.error("Managed Identity Error:", {
      message: error.message,
      code: error.code,
      statusCode: error.statusCode,
      identityType: MANAGED_IDENTITY_CONFIG.type,
      clientId: MANAGED_IDENTITY_CONFIG.clientId
    });

    // Provide actionable error messages
    if (error.code === "CredentialUnavailable") {
      throw new Error(
        "Managed identity is not available. Ensure it is enabled on the Azure resource."
      );
    }

    if (error.statusCode === 403) {
      throw new Error(
        "Access denied. Grant the required RBAC permissions to the managed identity."
      );
    }

    throw error;
  }
}

/**
 * BEST PRACTICE #5: Warm up credentials during application startup
 */
async function warmUpCredentials(credential: ManagedIdentityCredential) {
  const startTime = Date.now();

  try {
    console.log("Warming up managed identity credential...");
    await credential.getToken("https://management.azure.com/.default");

    const duration = Date.now() - startTime;
    console.log(`✓ Credential warmed up in ${duration}ms`);

    return true;
  } catch (error: any) {
    console.error("✗ Failed to warm up credential:", error.message);
    return false;
  }
}

/**
 * BEST PRACTICE #6: Implement retry logic for transient failures
 */
async function getTokenWithRetry(
  credential: ManagedIdentityCredential,
  scope: string,
  maxRetries: number = 3
): Promise<any> {
  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const token = await credential.getToken(scope);
      return token;
    } catch (error: any) {
      lastError = error;

      // Only retry on transient errors
      if (error.code === "ManagedIdentityCredential_Timeout" && attempt < maxRetries) {
        const delay = Math.pow(2, attempt) * 1000; // Exponential backoff
        console.log(`Retry ${attempt}/${maxRetries} after ${delay}ms...`);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }

      // Don't retry on permanent errors
      if (error.statusCode === 403 || error.statusCode === 404) {
        throw error;
      }
    }
  }

  throw lastError;
}

/**
 * BEST PRACTICE #7: Use least privilege principle
 * Grant only the minimum required permissions to the managed identity
 */
const RBAC_ROLES_BY_SERVICE = {
  keyVault: [
    "Key Vault Secrets User",      // Read secrets
    "Key Vault Secrets Officer"    // Manage secrets
  ],
  storage: [
    "Storage Blob Data Reader",    // Read blobs
    "Storage Blob Data Contributor" // Read/write blobs
  ],
  cosmosDb: [
    "Cosmos DB Account Reader Role", // Read account metadata
    "Cosmos DB Built-in Data Reader" // Read data
  ],
  sql: [
    "SQL DB Contributor",           // Manage databases
    "SQL Server Contributor"        // Manage servers
  ]
};

/**
 * BEST PRACTICE #8: Monitor managed identity usage
 */
interface IdentityUsageMetrics {
  tokenRequests: number;
  successfulAuths: number;
  failedAuths: number;
  lastUsed: Date;
  averageTokenDuration: number;
}

class ManagedIdentityMonitor {
  private metrics: IdentityUsageMetrics = {
    tokenRequests: 0,
    successfulAuths: 0,
    failedAuths: 0,
    lastUsed: new Date(),
    averageTokenDuration: 0
  };

  async getTokenWithMonitoring(
    credential: ManagedIdentityCredential,
    scope: string
  ) {
    const startTime = Date.now();
    this.metrics.tokenRequests++;

    try {
      const token = await credential.getToken(scope);

      const duration = Date.now() - startTime;
      this.metrics.successfulAuths++;
      this.metrics.lastUsed = new Date();
      this.metrics.averageTokenDuration = 
        (this.metrics.averageTokenDuration + duration) / 2;

      console.log("Token acquired successfully:", {
        duration: `${duration}ms`,
        expiresAt: new Date(token.expiresOnTimestamp)
      });

      return token;
    } catch (error) {
      this.metrics.failedAuths++;
      console.error("Token acquisition failed:", error);
      throw error;
    }
  }

  getMetrics(): IdentityUsageMetrics {
    return { ...this.metrics };
  }

  logMetrics(): void {
    console.log("Managed Identity Metrics:", {
      ...this.metrics,
      successRate: `${(this.metrics.successfulAuths / this.metrics.tokenRequests * 100).toFixed(2)}%`
    });
  }
}

/**
 * BEST PRACTICE #9: Test locally before deploying
 */
async function testLocalDevelopmentSetup() {
  console.log("Testing local development setup...");
  console.log("Current environment:", {
    isAzure: !!(process.env.WEBSITE_INSTANCE_ID || process.env.CONTAINER_APP_NAME),
    hasAzureCli: await checkAzureCliAvailable(),
    identityType: MANAGED_IDENTITY_CONFIG.type,
