    const token = await credential.getToken("https://management.azure.com/.default");
    console.log("✓ DefaultAzureCredential working");
    return true;
  } catch (error) {
    console.error("✗ DefaultAzureCredential failed:", error);
    return false;
  }
}

async function checkAzureCliAvailable(): Promise<boolean> {
  try {
    const { execSync } = require("child_process");
    execSync("az account show", { stdio: "ignore" });
    return true;
  } catch {
    return false;
