  } catch (error: any) {
    if (error.name === 'CredentialUnavailableError') {
      console.error('❌ Managed identity not available');
      console.error('   This is expected when running locally\n');

      console.log('✓ SOLUTION: Use DefaultAzureCredential instead');
      console.log('  const credential = new DefaultAzureCredential();');
    } else {
      throw error;
    }
  }
}

/**
 * Common Pitfall 2: Wrong Client ID for User-Assigned Identity
 */
export async function pitfall2_WrongClientId(): Promise<void> {
  console.log('Pitfall 2: Wrong Client ID\n');

  const wrongClientId = '00000000-0000-0000-0000-000000000000'; // ❌ Wrong ID

  try {
    const credential = new ManagedIdentityCredential({ 
      clientId: wrongClientId 
    });

    const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential
    );

    await blobServiceClient.getAccountInfo();
  } catch (error: any) {
    console.error('❌ Authentication failed with wrong client ID');
    console.error(`   Error: ${error.message}\n`);

    console.log('✓ SOLUTION:');
    console.log('  1. Verify client ID in Azure Portal:');
    console.log('     Portal → Managed Identities → [Your Identity] → Properties → Client ID');
    console.log('  2. Ensure the identity is assigned to your resource:');
    console.log('     Portal → [Your Resource] → Identity → User assigned → Add');
    console.log('  3. Check environment variable:');
    console.log('     echo $USER_ASSIGNED_IDENTITY_CLIENT_ID');
  }
}

/**
 * Common Pitfall 3: Missing RBAC Role Assignments
 */
export async function pitfall3_MissingRbacRoles(): Promise<void> {
  console.log('Pitfall 3: Missing RBAC Role Assignments\n');

  try {
    const credential = new DefaultAzureCredential();

    const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';
    const client = new SecretClient(vaultUrl, credential);

    // This will fail if identity doesn't have Key Vault permissions
    await client.getSecret('my-secret');
    console.log('✓ Successfully accessed Key Vault');
  } catch (error: any) {
    if (error.statusCode === 403 || error.code === 'Forbidden') {
      console.error('❌ Access denied (403 Forbidden)');
      console.error(`   Error: ${error.message}\n`);

      console.log('✓ SOLUTION: Grant appropriate RBAC roles');
      console.log('\n  For Key Vault (using Azure RBAC):');
      console.log('    az role assignment create \\');
      console.log('      --role "Key Vault Secrets User" \\');
      console.log('      --assignee <managed-identity-principal-id> \\');
      console.log('      --scope /subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.KeyVault/vaults/{vault}');
      console.log('\n  For Key Vault (using Access Policies):');
      console.log('    az keyvault set-policy \\');
      console.log('      --name <vault-name> \\');
      console.log('      --object-id <managed-identity-principal-id> \\');
      console.log('      --secret-permissions get list');
      console.log('\n  For Storage Account:');
      console.log('    az role assignment create \\');
      console.log('      --role "Storage Blob Data Contributor" \\');
      console.log('      --assignee <managed-identity-principal-id> \\');
      console.log('      --scope /subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.Storage/storageAccounts/{account}');
      console.log('\n  Note: Role assignments can take 5-10 minutes to propagate');
    } else {
      throw error;
    }
  }
}

/**
 * Common Pitfall 4: Not Reusing Credential Instances
 */
export async function pitfall4_NotReusingCredentials(): Promise<void> {
  console.log('Pitfall 4: Not Reusing Credential Instances\n');

  console.log('❌ BAD: Creating new credential for each client');
  console.log('  const blob = new BlobServiceClient(url, new DefaultAzureCredential());');
  console.log('  const secret = new SecretClient(vault, new DefaultAzureCredential());');
  console.log('  → Each credential instance makes separate auth calls\n');

  console.log('✓ GOOD: Reuse credential instance');
  console.log('  const credential = new DefaultAzureCredential();');
  console.log('  const blob = new BlobServiceClient(url, credential);');
  console.log('  const secret = new SecretClient(vault, credential);');
  console.log('  → Credential caches tokens across clients\n');

  // Demonstrate the good pattern
  const credential = new DefaultAzureCredential();

  const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
  const vaultUrl = process.env.KEY_VAULT_URL || 'https://myvault.vault.azure.net';

  try {
    const blobServiceClient = new BlobServiceClient(
      `https://${accountName}.blob.core.windows.net`,
      credential // ✓ Reusing same credential
    );

    const secretClient = new SecretClient(
      vaultUrl,
      credential // ✓ Reusing same credential
    );

    await Promise.all([
      blobServiceClient.getAccountInfo(),
      secretClient.listPropertiesOfSecrets().next()
    ]);

    console.log('✓ Successfully reused credential across multiple clients');
  } catch (error: any) {
    console.error('Note: This example requires proper configuration to run');
  }
}

/**
 * Common Pitfall 5: Ignoring Token Expiration
 */
export async function pitfall5_TokenExpiration(): Promise<void> {
  console.log('Pitfall 5: Token Expiration\n');

  const credential = new DefaultAzureCredential();

  // Get a token manually (usually SDK handles this)
  try {
    const token = await credential.getToken('https://storage.azure.com/.default');

    const expiresIn = Math.round((token.expiresOnTimestamp - Date.now()) / 1000 / 60);
    console.log(`Token obtained: expires in ${expiresIn} minutes`);
    console.log(`  Expiry time: ${new Date(token.expiresOnTimestamp).toISOString()}`);

    console.log('\n✓ GOOD NEWS: Azure SDK automatically handles token refresh');
    console.log('  - SDK requests new token before expiration');
    console.log('  - No manual token management needed');
    console.log('  - Just keep using the same credential instance\n');

    console.log('❌ However, be aware of long-running operations:');
    console.log('  - Very long-running tasks (hours) may need error handling');
    console.log('  - Credential may become invalid if identity is removed');
    console.log('  - Network issues during token refresh can cause failures');
  } catch (error: any) {
    console.error('Failed to obtain token:', error.message);
  }
}

/**
 * Best Practice: Comprehensive Error Handler
 */
export async function handleManagedIdentityError(
  error: any,
  operation: string,
  serviceName: string
): Promise<void> {
  console.error(`\n❌ ${operation} failed on ${serviceName}\n`);

  // 1. Credential unavailable
  if (error.name === 'CredentialUnavailableError') {
    console.error('Issue: Managed identity not available');
    console.error('Possible causes:');
    console.error('  - Not running on Azure (expected in local dev)');
    console.error('  - Managed identity not enabled on resource');
    console.error('  - IDENTITY_ENDPOINT not set\n');
    console.error('Solutions:');
    console.error('  Azure: Enable managed identity on your resource');
    console.error('  Local: Use DefaultAzureCredential + az login');
    return;
  }

  // 2. Authorization errors (403)
  if (error.statusCode === 403 || error.code === 'Forbidden') {
    console.error('Issue: Authorization denied');
    console.error('Possible causes:');
    console.error('  - Missing RBAC role assignment');
    console.error('  - Wrong scope for role assignment');
    console.error('  - Role assignment not yet propagated (5-10 min delay)\n');
    console.error('Solutions:');
    console.error('  1. Check role assignments:');
    console.error('     az role assignment list --assignee <identity-principal-id>');
    console.error('  2. Grant required role:');
    console.error(`     az role assignment create --role "<RoleName>" --assignee <identity-principal-id>`);
    console.error('  3. Wait 5-10 minutes for propagation');
    return;
  }

  // 3. Authentication errors
  if (error.message?.includes('authentication') || error.message?.includes('ManagedIdentityCredential')) {
    console.error('Issue: Authentication failed');
    console.error('Possible causes:');
    console.error('  - Invalid client ID (user-assigned identity)');
    console.error('  - Identity not assigned to resource');
    console.error('  - Managed identity service temporarily unavailable\n');
    console.error('Solutions:');
    console.error('  1. Verify client ID in Azure Portal');
    console.error('  2. Confirm identity assignment:');
    console.error('     az identity list --query "[?principalId!=null]"');
    console.error('  3. Check Azure service health');
    return;
  }

  // 4. Network errors
  if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
    console.error('Issue: Network connectivity problem');
    console.error('Possible causes:');
    console.error('  - Service endpoint unreachable');
    console.error('  - Firewall blocking outbound traffic');
    console.error('  - Incorrect service URL\n');
    console.error('Solutions:');
    console.error('  1. Check network connectivity');
    console.error('  2. Verify service endpoint URL');
    console.error('  3. Review firewall rules');
    return;
  }

  // 5. Aggregate errors (from DefaultAzureCredential)
  if (error.name === 'AggregateAuthenticationError') {
    console.error('Issue: All credential sources failed');
    console.error('Attempted credentials:');
    const aggError = error as AggregateAuthenticationError;
    aggError.errors.forEach((err: any, index: number) => {
      console.error(`  ${index + 1}. ${err.name}: ${err.message}`);
    });
    console.error('\nSolutions:');
    console.error('  - Ensure at least one credential source is properly configured');
    console.error('  - Azure: Enable managed identity');
    console.error('  - Local: Run az login or set environment variables');
    return;
  }

  // 6. Resource not found (404)
  if (error.statusCode === 404) {
    console.error('Issue: Resource not found');
    console.error(`  The requested ${serviceName} resource doesn't exist\n`);
    console.error('Solutions:');
    console.error('  1. Verify resource name and URL');
    console.error('  2. Check if resource exists in correct subscription');
    console.error('  3. Confirm you have read permissions');
    return;
  }

  // 7. Generic fallback
  console.error('Issue: Unexpected error');
  console.error(`  Error name: ${error.name || 'Unknown'}`);
  console.error(`  Error code: ${error.code || 'N/A'}`);
  console.error(`  Status code: ${error.statusCode || 'N/A'}`);
  console.error(`  Message: ${error.message}`);
  console.error('\nFull error object:');
  console.error(error);
}

/**
 * Best Practice: Retry with Exponential Backoff
 */
export async function retryWithBackoff<T>(
  operation: () => Promise<T>,
  maxRetries: number = 3,
  initialDelayMs: number = 1000
): Promise<T> {
  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      // Don't retry authorization errors - they won't fix themselves
      if (error.statusCode === 403 || error.statusCode === 401) {
        throw error;
      }

      // Don't retry invalid configuration errors
      if (error.message?.includes('invalid') || error.message?.includes('not found')) {
        throw error;
      }

      if (attempt === maxRetries) {
        throw error;
      }

      // Exponential backoff
      const delayMs = initialDelayMs * Math.pow(2, attempt - 1);
      console.log(`  Retry ${attempt}/${maxRetries} after ${delayMs}ms...`);
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }

  throw lastError;
}

// Example usage of retry
export async function useWithRetry(): Promise<void> {
  console.log('Using retry with exponential backoff\n');

  try {
    await retryWithBackoff(async () => {
      const credential = new DefaultAzureCredential();
      const accountName = process.env.STORAGE_ACCOUNT_NAME || 'mystorageaccount';
      const blobServiceClient = new BlobServiceClient(
        `https://${accountName}.blob.core.windows.net`,
        credential
      );

      await blobServiceClient.getAccountInfo();
      console.log('✓ Operation succeeded');
    }, 3, 1000);
  } catch (error: any) {
    await handleManagedIdentityError(error, 'Get account info', 'Azure Storage');
  }
}

// Example usage
if (require.main === module) {
  (async () => {
    console.log('=== Error Handling and Common Pitfalls ===\n');

    await pitfall1_NotHandlingUnavailableCredential();
    console.log('\n---\n');

    await pitfall3_MissingRbacRoles();
    console.log('\n---\n');

    await pitfall4_NotReusingCredentials();
    console.log('\n---\n');

    await pitfall5_TokenExpiration();
    console.log('\n---\n');

    await useWithRetry();
  })();
}
