 * Azure Event Hubs TypeScript Demo
 * 
 * Demonstrates:
 * - Creating and sending event batches with custom properties
 * - Consuming events with checkpoint store
 * - Graceful shutdown
 * 
 * Required packages:
 * npm install @azure/event-hubs @azure/eventhubs-checkpointstore-blob @azure/storage-blob
 */

import {
  EventHubProducerClient,
  EventHubConsumerClient,
  ReceivedEventData,
  PartitionContext,
  Subscription
} from "@azure/event-hubs";
import { ContainerClient } from "@azure/storage-blob";
import { BlobCheckpointStore } from "@azure/eventhubs-checkpointstore-blob";

// Configuration - Replace with your actual connection strings
const EVENT_HUB_CONNECTION_STRING = process.env.EVENT_HUB_CONNECTION_STRING || "Endpoint=sb://YOUR_NAMESPACE.servicebus.windows.net/;SharedAccessKeyName=YOUR_KEY_NAME;SharedAccessKey=YOUR_KEY";
const EVENT_HUB_NAME = process.env.EVENT_HUB_NAME || "your-event-hub-name";
const STORAGE_CONNECTION_STRING = process.env.STORAGE_CONNECTION_STRING || "DefaultEndpointsProtocol=https;AccountName=YOUR_ACCOUNT;AccountKey=YOUR_KEY;EndpointSuffix=core.windows.net";
const STORAGE_CONTAINER_NAME = process.env.STORAGE_CONTAINER_NAME || "eventhubs-checkpoints";
const CONSUMER_GROUP = process.env.CONSUMER_GROUP || "$Default";

/**
 * Producer: Sends a batch of events to Event Hubs
 */
async function produceEvents(): Promise<void> {
  console.log("=== Starting Event Producer ===\n");

  // Create the producer client
  const producer = new EventHubProducerClient(
    EVENT_HUB_CONNECTION_STRING,
    EVENT_HUB_NAME
  );

  try {
    // Create a batch of events
    const batch = await producer.createBatch();
    console.log(`Created batch with max size: ${batch.maxSizeInBytes} bytes\n`);

    // Add 10 events with custom properties
    for (let i = 1; i <= 10; i++) {
      const eventData = {
        body: {
          message: `Event message ${i}`,
          timestamp: new Date().toISOString(),
          sequenceNumber: i
        },
        properties: {
          eventType: "demo",
          priority: i % 2 === 0 ? "high" : "low",
          source: "typescript-demo",
          customerId: `CUST-${1000 + i}`
        }
      };

      const wasAdded = batch.tryAdd(eventData);

      if (!wasAdded) {
        console.warn(`Event ${i} could not be added (batch full)`);
        break;
      }

      console.log(`✓ Added event ${i} to batch`);
    }

    // Send the batch
    console.log(`\nSending batch of ${batch.count} events...`);
    await producer.sendBatch(batch);
    console.log("✓ Batch sent successfully!\n");

  } catch (error) {
    console.error("Error in producer:", error);
    throw error;
  } finally {
    // Close the producer
    await producer.close();
    console.log("Producer closed.\n");
  }
}

/**
 * Consumer: Receives events from Event Hubs with checkpointing
 */
async function consumeEvents(): Promise<Subscription> {
  console.log("=== Starting Event Consumer ===\n");

  // Create blob container client for checkpoint store
  const containerClient = new ContainerClient(
    STORAGE_CONNECTION_STRING,
    STORAGE_CONTAINER_NAME
  );

  // Create the checkpoint store
  const checkpointStore = new BlobCheckpointStore(containerClient);

  // Create the consumer client
  const consumer = new EventHubConsumerClient(
    CONSUMER_GROUP,
    EVENT_HUB_CONNECTION_STRING,
    EVENT_HUB_NAME,
    checkpointStore
  );

  console.log(`Consumer connected to Event Hub: ${EVENT_HUB_NAME}`);
  console.log(`Consumer group: ${CONSUMER_GROUP}\n`);

  let eventCount = 0;

  // Subscribe to events
  const subscription = consumer.subscribe({
    /**
     * Process events handler
     */
    processEvents: async (
      events: ReceivedEventData[],
      context: PartitionContext
    ): Promise<void> => {
      if (events.length === 0) {
        return;
      }

      console.log(`\n--- Received ${events.length} event(s) from partition: ${context.partitionId} ---`);

      for (const event of events) {
        eventCount++;

        // Print event details
        console.log(`\nEvent #${eventCount}:`);
        console.log(`  Partition: ${context.partitionId}`);
        console.log(`  Sequence Number: ${event.sequenceNumber}`);
        console.log(`  Offset: ${event.offset}`);
        console.log(`  Enqueued Time: ${event.enqueuedTimeUtc}`);

        // Print event body
        console.log(`  Body:`, JSON.stringify(event.body, null, 2));

        // Print custom properties
        if (event.properties && Object.keys(event.properties).length > 0) {
          console.log(`  Properties:`, event.properties);
        }

        // Print system properties
        if (event.systemProperties) {
          console.log(`  System Properties:`, {
            sequenceNumber: event.systemProperties.sequenceNumber,
            offset: event.systemProperties.offset,
            enqueuedTimeUtc: event.systemProperties.enqueuedTimeUtc
          });
        }
      }

      // Update checkpoint after processing all events in this batch
      try {
        await context.updateCheckpoint(events[events.length - 1]);
        console.log(`\n✓ Checkpoint updated for partition ${context.partitionId}`);
      } catch (error) {
        console.error(`Error updating checkpoint:`, error);
      }
    },

    /**
     * Process errors handler
     */
    processError: async (error: Error, context: PartitionContext): Promise<void> => {
      console.error(`\n❌ Error on partition ${context.partitionId}:`, error);
    }
  });

  console.log("✓ Subscribed to events. Listening...\n");

  return subscription;
}

/**
 * Main execution flow with graceful shutdown
 */
async function main(): Promise<void> {
  console.log("╔═══════════════════════════════════════════╗");
  console.log("║  Azure Event Hubs TypeScript Demo        ║");
  console.log("╚═══════════════════════════════════════════╝\n");

  let subscription: Subscription | null = null;

  try {
    // Step 1: Produce events
    await produceEvents();

    // Wait a moment for events to be available
    console.log("Waiting 3 seconds for events to be available...\n");
    await new Promise(resolve => setTimeout(resolve, 3000));

    // Step 2: Consume events
    subscription = await consumeEvents();

    // Listen for events for 15 seconds
    console.log("Listening for events for 15 seconds...");
    console.log("(Press Ctrl+C to stop earlier)\n");
    await new Promise(resolve => setTimeout(resolve, 15000));

  } catch (error) {
    console.error("\n❌ Fatal error:", error);
    process.exit(1);
  } finally {
    // Graceful shutdown
    console.log("\n\n=== Graceful Shutdown ===");

    if (subscription) {
      console.log("Closing subscription...");
      await subscription.close();
      console.log("✓ Subscription closed");
    }

    console.log("\n✓ Demo completed successfully!");
  }
}

// Handle process termination signals for graceful shutdown
process.on("SIGINT", async () => {
  console.log("\n\nReceived SIGINT signal. Shutting down gracefully...");
  process.exit(0);
});

process.on("SIGTERM", async () => {
  console.log("\n\nReceived SIGTERM signal. Shutting down gracefully...");
  process.exit(0);
});

// Run the demo
main().catch((error) => {
  console.error("Unhandled error:", error);
  process.exit(1);
});
