      } else if (info.expiresOn) {
        console.log(
          `✓ Secret '${info.name}' expires on ${info.expiresOn} (${info.daysUntilExpiry} days)`
        );
      } else {
        console.log(`✓ Secret '${info.name}' has no expiration date set.`);
      }
    }
    console.log();

    // Step 6: Demonstrate secret rotation
    console.log('STEP 6: Secret Rotation Demo');
    console.log('-'.repeat(80));

    const testSecretName = 'test-rotation-secret';

    // Create initial secret
    console.log(`Creating initial secret '${testSecretName}'...`);
    const expiryDate = new Date();
    expiryDate.setDate(expiryDate.getDate() + 30); // Expires in 30 days

    const initialVersion = await config.rotationHelper.rotateSecret(
      testSecretName,
      'initial-secret-value-v1',
      {
        expiresOn: expiryDate,
        tags: { rotated: 'false', version: '1' },
      }
    );
    console.log(`Initial version created: ${initialVersion}`);
    console.log();

    // Rotate the secret (create new version)
    console.log('Rotating secret with new value and expiry...');
    const newExpiryDate = new Date();
    newExpiryDate.setDate(newExpiryDate.getDate() + 60); // Expires in 60 days

    const newVersion = await config.rotationHelper.rotateSecret(
      testSecretName,
      'rotated-secret-value-v2',
      {
        expiresOn: newExpiryDate,
        tags: { rotated: 'true', version: '2' },
      }
    );
    console.log(`New version created: ${newVersion}`);
    console.log();

    // List all versions
    console.log('Listing all versions of the secret...');
    const versions = await config.rotationHelper.listSecretVersions(
      testSecretName
    );
    console.log(`Found ${versions.length} version(s):`);
    versions.forEach((v, idx) => {
      console.log(
        `  ${idx + 1}. Version ${v.version} - Enabled: ${v.enabled}, Created: ${v.createdOn}`
      );
    });
    console.log();

    // Step 7: Demonstrate delete and purge cleanup
    console.log('STEP 7: Delete and Purge Cleanup Demo');
