{"file_text":"import { SecretClient, KeyVaultSecret } from '@azure/keyvault-secrets';

export interface SecretMetadata {
  value: string;
  version?: string;
  expiresOn?: Date;
  name: string;
}

export class SecretProvider {
  constructor(private client: SecretClient) {}

  /**
   * Retrieve a secret by name with optional default value if not found
   */
  async getSecret(
    secretName: string,
    defaultValue?: string
  ): Promise<SecretMetadata | null> {
    try {
      const secret = await this.client.getSecret(secretName);
      return this.mapToMetadata(secret);
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`Secret '${secretName}' not found in Key Vault`);
        if (defaultValue !== undefined) {
          return {
            name: secretName,
            value: defaultValue,
            version: undefined,
            expiresOn: undefined,
          };
        }
        return null;
      }
      throw error;
    }
  }

  /**
   * Retrieve a specific version of a secret
   */
  async getSecretVersion(
    secretName: string,
    version: string
  ): Promise<SecretMetadata | null> {
    try {
      const secret = await this.client.getSecret(secretName, { version });
      return this.mapToMetadata(secret);
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(
          `Secret '${secretName}' version '${version}' not found`
        );
        return null;
      }
      throw error;
    }
  }

  /**
   * Check if a secret is expiring within the specified number of days
   */
  isExpiringWithin(secret: SecretMetadata, days: number): boolean {
    if (!secret.expiresOn) {
      return false;
    }

    const now = new Date();
    const warningDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
    return secret.expiresOn <= warningDate;
  }

  /**
   * Get days until expiry (negative if already expired)
   */
  getDaysUntilExpiry(secret: SecretMetadata): number | null {
    if (!secret.expiresOn) {
      return null;
    }

    const now = new Date();
    const diff = secret.expiresOn.getTime() - now.getTime();
    return Math.floor(diff / (24 * 60 * 60 * 1000));
  }

  private mapToMetadata(secret: KeyVaultSecret): SecretMetadata {
    return {
      name: secret.name,
      value: secret.value || '',
      version: secret.properties.version,
      expiresOn: secret.properties.expiresOn,
    };
  }
}
