  }
  if (!containerName) {
    throw new Error("AZURE_STORAGE_CONTAINER_NAME is required.");
  }

  return {
    accountUrl,
    containerName,
    maxRetries: Number(process.env.AZURE_STORAGE_MAX_RETRIES ?? 5),
    retryDelayMs: Number(process.env.AZURE_STORAGE_RETRY_DELAY_MS ?? 800),
