  expiresOn?: Date;
  enabled?: boolean;
}

export class SecretProvider {
  private client: SecretClient;

  constructor(client: SecretClient) {
    this.client = client;
  }

  /**
   * Retrieves a secret from Key Vault by name.
   * Returns the default value if the secret doesn't exist.
   */
  async getSecret(
    secretName: string,
    defaultValue: string = ''
  ): Promise<string> {
    try {
      const secret = await this.client.getSecret(secretName);
      return secret.value || defaultValue;
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`Secret '${secretName}' not found, using default value`);
        return defaultValue;
      }
      throw error;
    }
  }

  /**
   * Retrieves a specific version of a secret from Key Vault.
   */
  async getSecretVersion(
    secretName: string,
    version: string,
    defaultValue: string = ''
  ): Promise<string> {
    try {
      const secret = await this.client.getSecret(secretName, { version });
      return secret.value || defaultValue;
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(
          `Secret '${secretName}' version '${version}' not found, using default value`
        );
        return defaultValue;
      }
      throw error;
    }
  }

  /**
   * Retrieves secret metadata including expiry date.
   */
  async getSecretMetadata(secretName: string): Promise<SecretMetadata | null> {
    try {
      const secret = await this.client.getSecret(secretName);
      return {
        value: secret.value || '',
        version: secret.properties.version,
        expiresOn: secret.properties.expiresOn,
        enabled: secret.properties.enabled,
      };
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`Secret '${secretName}' not found`);
        return null;
      }
      throw error;
    }
  }

  /**
   * Checks if a secret is expiring within the specified number of days.
   */
  isSecretExpiringSoon(expiresOn: Date | undefined, daysThreshold: number): boolean {
    if (!expiresOn) {
      return false;
    }

    const now = new Date();
    const thresholdDate = new Date();
    thresholdDate.setDate(now.getDate() + daysThreshold);

    return expiresOn <= thresholdDate && expiresOn > now;
  }

  /**
   * Gets the Key Vault client for advanced operations.
   */
  getClient(): SecretClient {
    return this.client;
  }
}
