{"file_text":"import { SecretProvider, SecretMetadata } from './secretProvider';

interface CachedSecret {
  value: string;
  expiresOn?: Date;
  cachedAt: Date;
}

export class CachingSecretProvider {
  private provider: SecretProvider;
  private cache: Map<string, CachedSecret>;
  private expiryWarningDays: number;

  constructor(provider: SecretProvider, expiryWarningDays: number = 7) {
    this.provider = provider;
    this.cache = new Map();
    this.expiryWarningDays = expiryWarningDays;
  }

  /**
   * Bulk-loads a predefined set of required configuration keys at startup.
   */
  async bulkLoad(secretNames: string[]): Promise<void> {
    console.log(`Bulk loading ${secretNames.length} secrets...`);

    const promises = secretNames.map(async (name) => {
      try {
        const metadata = await this.provider.getSecretMetadata(name);
        if (metadata) {
          this.cache.set(name, {
            value: metadata.value,
            expiresOn: metadata.expiresOn,
            cachedAt: new Date(),
          });
          console.log(`  ✓ Loaded: ${name}`);
        }
      } catch (error) {
        console.error(`  ✗ Failed to load ${name}:`, error);
      }
    });

    await Promise.all(promises);
    console.log('Bulk load complete\n');
  }

  /**
   * Retrieves a secret from cache, or fetches from Key Vault if not cached.
   */
  async getSecret(secretName: string, defaultValue: string = ''): Promise<string> {
    const cached = this.cache.get(secretName);

    if (cached) {
      // Check if secret is expiring soon and auto-refresh
      if (this.shouldRefresh(cached)) {
        console.log(`Secret '${secretName}' is expiring soon, auto-refreshing...`);
        await this.refresh(secretName);
        return this.cache.get(secretName)?.value || defaultValue;
      }
      return cached.value;
    }

    // Not in cache, fetch from Key Vault
    const metadata = await this.provider.getSecretMetadata(secretName);
    if (metadata) {
      this.cache.set(secretName, {
        value: metadata.value,
        expiresOn: metadata.expiresOn,
        cachedAt: new Date(),
      });
      return metadata.value;
    }

    return defaultValue;
  }

  /**
   * On-demand refresh of an individual secret key.
   */
  async refresh(secretName: string): Promise<void> {
    console.log(`Refreshing secret: ${secretName}`);
    const metadata = await this.provider.getSecretMetadata(secretName);

    if (metadata) {
      this.cache.set(secretName, {
        value: metadata.value,
        expiresOn: metadata.expiresOn,
        cachedAt: new Date(),
      });
      console.log(`  ✓ Refreshed: ${secretName}\n`);
    } else {
      console.warn(`  ✗ Could not refresh: ${secretName}\n`);
    }
  }

  /**
   * Checks if a cached secret should be refreshed based on expiry warning window.
   */
  private shouldRefresh(cached: CachedSecret): boolean {
    if (!cached.expiresOn) {
      return false;
    }

    return this.provider.isSecretExpiringSoon(
      cached.expiresOn,
      this.expiryWarningDays
    );
  }

  /**
   * Gets all secrets that are expiring within the warning window.
   */
  getExpiringSoonSecrets(): Array<{ name: string; expiresOn: Date }> {
    const expiring: Array<{ name: string; expiresOn: Date }> = [];

    for (const [name, cached] of this.cache.entries()) {
      if (cached.expiresOn && this.shouldRefresh(cached)) {
        expiring.push({ name, expiresOn: cached.expiresOn });
      }
    }

    return expiring;
  }

  /**
   * Clears the entire cache.
   */
  clearCache(): void {
    this.cache.clear();
    console.log('Cache cleared\n');
  }

  /**
   * Removes a specific secret from cache.
   */
  evict(secretName: string): void {
    this.cache.delete(secretName);
  }

  /**
   * Gets cache statistics.
   */
  getCacheStats(): { size: number; keys: string[] } {
    return {
      size: this.cache.size,
      keys: Array.from(this.cache.keys()),
    };
  }
}
