import { DefaultAzureCredential } from '@azure/identity';
import { SecretProvider } from './secretProvider';
import { CachingSecretProvider } from './cachingProvider';

export class ConfigurationModule {
  private secretClient: SecretClient;
  private secretProvider: SecretProvider;
  private cachingProvider: CachingSecretProvider;

  constructor(expiryWarningDays: number = 7) {
    const vaultUrl = process.env.AZURE_KEY_VAULT_URL;

    if (!vaultUrl) {
      throw new Error(
        'AZURE_KEY_VAULT_URL environment variable is not set. ' +
        'Please set it to your Key Vault URL (e.g., https://my-vault.vault.azure.net/)'
      );
    }

    // Authenticate using managed identity (DefaultAzureCredential)
    // In Azure, this will use managed identity automatically
    // For local development, it will try multiple auth methods (Azure CLI, etc.)
    const credential = new DefaultAzureCredential();

    this.secretClient = new SecretClient(vaultUrl, credential);
    this.secretProvider = new SecretProvider(this.secretClient);
    this.cachingProvider = new CachingSecretProvider(
      this.secretProvider,
      expiryWarningDays
    );

    console.log(`✓ Connected to Key Vault: ${vaultUrl}`);
    console.log(`✓ Using managed identity authentication\n`);
  }

  /**
   * Gets the secret provider (direct access to Key Vault).
   */
  getSecretProvider(): SecretProvider {
    return this.secretProvider;
  }

  /**
   * Gets the caching provider (recommended for application use).
   */
  getCachingProvider(): CachingSecretProvider {
    return this.cachingProvider;
  }

  /**
   * Gets the underlying Secret Client for advanced operations.
   */
  getSecretClient(): SecretClient {
    return this.secretClient;
  }
}
