{"file_text":"import { SecretClient } from '@azure/keyvault-secrets';

export interface RotationOptions {
  expiresOn?: Date;
  contentType?: string;
  enabled?: boolean;
}

export class SecretRotationHelper {
  private client: SecretClient;

  constructor(client: SecretClient) {
    this.client = client;
  }

  /**
   * Rotates a secret by creating a new version with the updated value.
   * Key Vault maintains multiple versions per secret name.
   */
  async rotateSecret(
    secretName: string,
    newValue: string,
    options: RotationOptions = {}
  ): Promise<string> {
    console.log(`Rotating secret: ${secretName}`);

    try {
      const secret = await this.client.setSecret(secretName, newValue, {
        expiresOn: options.expiresOn,
        contentType: options.contentType,
        enabled: options.enabled !== undefined ? options.enabled : true,
      });

      console.log(`  ✓ New version created: ${secret.properties.version}`);
      return secret.properties.version || '';
    } catch (error) {
      console.error(`  ✗ Failed to rotate secret '${secretName}':`, error);
      throw error;
    }
  }

  /**
   * Safely deletes a secret and waits for the operation to complete.
   * With soft-delete enabled, the secret is not immediately removed.
   */
  async deleteSecret(secretName: string): Promise<void> {
    console.log(`Deleting secret: ${secretName}`);

    try {
      const poller = await this.client.beginDeleteSecret(secretName);

      // Wait for the long-running delete operation to complete
      await poller.pollUntilDone();

      console.log(`  ✓ Secret deleted (soft-delete): ${secretName}`);
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`  ! Secret '${secretName}' not found, nothing to delete`);
      } else {
        console.error(`  ✗ Failed to delete secret '${secretName}':`, error);
        throw error;
      }
    }
  }

  /**
   * Purges a soft-deleted secret permanently.
   * This must be called after deleteSecret and allows full name reuse.
   */
  async purgeSecret(secretName: string): Promise<void> {
    console.log(`Purging secret: ${secretName}`);

    try {
      await this.client.purgeDeletedSecret(secretName);
      console.log(`  ✓ Secret permanently purged: ${secretName}`);
    } catch (error: any) {
      if (error.statusCode === 404) {
        console.warn(`  ! Secret '${secretName}' not found in deleted secrets`);
      } else {
        console.error(`  ✗ Failed to purge secret '${secretName}':`, error);
        throw error;
      }
    }
  }

  /**
   * Full cleanup flow: delete and purge a secret.
   * Safe to call - handles the long-running delete operation before purging.
   */
  async deleteAndPurge(secretName: string): Promise<void> {
    console.log(`\n=== Full cleanup for secret: ${secretName} ===`);

    // Step 1: Delete (soft-delete with waiting)
    await this.deleteSecret(secretName);

    // Step 2: Purge permanently
    // Add a small delay to ensure the delete operation is fully propagated
    await new Promise(resolve => setTimeout(resolve, 2000));
    await this.purgeSecret(secretName);

    console.log(`✓ Cleanup complete for: ${secretName}\n`);
  }

  /**
   * Lists all versions of a secret.
   */
  async listSecretVersions(secretName: string): Promise<Array<{ version: string; enabled: boolean }>> {
    console.log(`Listing versions for secret: ${secretName}`);
    const versions: Array<{ version: string; enabled: boolean }> = [];

    try {
      for await (const properties of this.client.listPropertiesOfSecretVersions(secretName)) {
        versions.push({
          version: properties.version || 'unknown',
          enabled: properties.enabled || false,
        });
      }

      console.log(`  Found ${versions.length} version(s)\n`);
      return versions;
    } catch (error) {
      console.error(`  ✗ Failed to list versions for '${secretName}':`, error);
      return [];
    }
  }
}
