    const cachingProvider = config.getCachingProvider();
    const secretProvider = config.getSecretProvider();
    const rotationHelper = new SecretRotationHelper(config.getSecretClient());

    // Step 2: Bulk load configuration keys at startup
    console.log('📦 Step 2: Bulk Load Configuration Keys');
    console.log('-'.repeat(70));
    const requiredKeys = [
      'DatabaseConnectionString',
      'ApiKey',
      'StorageAccountKey',
    ];

    // Create demo secrets first (for the demo to work)
    console.log('Creating demo secrets for testing...');
    const expiresIn30Days = new Date();
    expiresIn30Days.setDate(expiresIn30Days.getDate() + 30);

    const expiresIn3Days = new Date();
    expiresIn3Days.setDate(expiresIn3Days.getDate() + 3);

    try {
      await config.getSecretClient().setSecret('DatabaseConnectionString', 
        'Server=myserver;Database=mydb;User=admin;Password=secure123', 
        { expiresOn: expiresIn30Days });
      await config.getSecretClient().setSecret('ApiKey', 
        'ak-1234567890abcdef', 
        { expiresOn: expiresIn3Days }); // This one expires soon!
      await config.getSecretClient().setSecret('StorageAccountKey', 
        'DefaultEndpointsProtocol=https;AccountName=myaccount;AccountKey=key123==', 
        { expiresOn: expiresIn30Days });
      console.log('Demo secrets created\n');
    } catch (error) {
      console.warn('Note: Could not create demo secrets (they may already exist or you may need permissions)\n');
    }

    await cachingProvider.bulkLoad(requiredKeys);

    // Step 3: Read secrets from cache
    console.log('📦 Step 3: Read Secrets from Cache');
    console.log('-'.repeat(70));
    for (const key of requiredKeys) {
      const value = await cachingProvider.getSecret(key, '<not-set>');
      const displayValue = value.length > 40 ? value.substring(0, 40) + '...' : value;
      console.log(`  ${key}: ${displayValue}`);
    }

    const stats = cachingProvider.getCacheStats();
    console.log(`\n  Cache stats: ${stats.size} secrets cached`);
    console.log();

    // Step 4: Refresh a single secret
    console.log('📦 Step 4: On-Demand Refresh');
    console.log('-'.repeat(70));
    await cachingProvider.refresh('ApiKey');

    // Step 5: Check for expiring secrets
    console.log('📦 Step 5: Check for Expiring Secrets');
    console.log('-'.repeat(70));
    const expiringSoon = cachingProvider.getExpiringSoonSecrets();

    if (expiringSoon.length > 0) {
      console.log(`⚠️  WARNING: ${expiringSoon.length} secret(s) expiring soon:\n`);
      for (const secret of expiringSoon) {
        const daysUntilExpiry = Math.ceil(
          (secret.expiresOn.getTime() - Date.now()) / (1000 * 60 * 60 * 24)
        );
        console.log(`  • ${secret.name}`);
        console.log(`    Expires: ${secret.expiresOn.toISOString()}`);
        console.log(`    Days remaining: ${daysUntilExpiry}`);
      }
    } else {
      console.log('✓ All secrets are current (no expiration warnings)');
    }
    console.log();

    // Step 6: Secret rotation demo
    console.log('📦 Step 6: Secret Rotation Demo');
    console.log('-'.repeat(70));

    const testSecretName = 'TestRotationSecret';

    // Create initial version
    console.log(`Creating initial secret: ${testSecretName}`);
    const expiresIn60Days = new Date();
    expiresIn60Days.setDate(expiresIn60Days.getDate() + 60);

    await rotationHelper.rotateSecret(
      testSecretName,
      'initial-value-v1',
      { expiresOn: expiresIn60Days }
    );
    console.log();

    // Wait a moment
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Rotate to new version
    const expiresIn90Days = new Date();
    expiresIn90Days.setDate(expiresIn90Days.getDate() + 90);

    const newVersion = await rotationHelper.rotateSecret(
      testSecretName,
      'rotated-value-v2',
      { expiresOn: expiresIn90Days }
    );
    console.log();

    // List versions
    await rotationHelper.listSecretVersions(testSecretName);

    // Verify we can read the new version
    const currentValue = await secretProvider.getSecret(testSecretName);
    console.log(`Current value: ${currentValue}`);
    console.log();

    // Step 7: Delete and purge demo
    console.log('📦 Step 7: Delete and Purge Demo');
    console.log('-'.repeat(70));

    await rotationHelper.deleteAndPurge(testSecretName);

    // Final summary
    console.log('='.repeat(70));
    console.log('✅ Demo Complete!');
    console.log('='.repeat(70));
    console.log();
    console.log('Summary:');
    console.log('  ✓ Connected to Key Vault using managed identity');
    console.log('  ✓ Bulk-loaded configuration keys');
    console.log('  ✓ Retrieved secrets from cache');
    console.log('  ✓ Refreshed individual secrets');
    console.log('  ✓ Detected expiring secrets');
    console.log('  ✓ Rotated a secret (created new version)');
    console.log('  ✓ Demonstrated safe delete-and-purge cleanup');
    console.log();

  } catch (error: any) {
    console.error('\n❌ Error during demo:', error.message);

    if (error.message.includes('AZURE_KEY_VAULT_URL')) {
      console.error('\nPlease set the AZURE_KEY_VAULT_URL environment variable:');
      console.error('  export AZURE_KEY_VAULT_URL=https://your-vault.vault.azure.net/');
    } else if (error.code === 'ENOTFOUND' || error.code === 'ETIMEDOUT') {
      console.error('\nNetwork error: Could not connect to Key Vault.');
      console.error('Make sure your Key Vault URL is correct and accessible.');
    } else if (error.statusCode === 401 || error.statusCode === 403) {
      console.error('\nAuthentication/Authorization error.');
      console.error('Make sure:');
      console.error('  1. You are authenticated (az login for local dev)');
      console.error('  2. Your identity has Key Vault permissions (Get, List, Set, Delete, Purge secrets)');
    }

    process.exit(1);
  }
}

// Run the demo
main();
