{"file_text":"import { DefaultAzureCredential } from '@azure/identity';
import { BlobServiceClient } from '@azure/storage-blob';
import { KeyClient } from '@azure/keyvault-keys';

export interface AzureConfig {
  storageAccountUrl: string;
  keyVaultUrl: string;
  keyName: string;
  containerName: string;
}

export interface AzureClients {
  blobServiceClient: BlobServiceClient;
  keyClient: KeyClient;
  config: AzureConfig;
}

export function loadConfig(): AzureConfig {
  const storageAccountUrl = process.env.AZURE_STORAGE_ACCOUNT_URL;
  const keyVaultUrl = process.env.AZURE_KEYVAULT_URL;
  const keyName = process.env.AZURE_KEY_NAME || 'encryption-key';
  const containerName = process.env.AZURE_CONTAINER_NAME || 'encrypted-files';

  if (!storageAccountUrl) {
    throw new Error('AZURE_STORAGE_ACCOUNT_URL environment variable is required');
  }

  if (!keyVaultUrl) {
    throw new Error('AZURE_KEYVAULT_URL environment variable is required');
  }

  return {
    storageAccountUrl,
    keyVaultUrl,
    keyName,
    containerName,
  };
}

export function initializeAzureClients(config: AzureConfig): AzureClients {
  const credential = new DefaultAzureCredential();

  const blobServiceClient = new BlobServiceClient(
    config.storageAccountUrl,
    credential
  );

  const keyClient = new KeyClient(config.keyVaultUrl, credential);

  return {
    blobServiceClient,
    keyClient,
    config,
  };
}
