{"file_text":"import { KeyClient } from '@azure/keyvault-keys';
import { createCipheriv, createDecipheriv, randomBytes } from 'crypto';

export interface WrappedKey {
  wrappedDataKey: string; // base64
  keyId: string;
}

export interface EncryptedData {
  ciphertext: Buffer;
  iv: string; // base64
  authTag: string; // base64
  wrappedKey: WrappedKey;
}

export class KeyManagement {
  constructor(
    private keyClient: KeyClient,
    private keyName: string
  ) {}

  async wrapDataKey(dataKey: Buffer): Promise<WrappedKey> {
    try {
      const key = await this.keyClient.getKey(this.keyName);

      if (!key.key) {
        throw new Error(`Key ${this.keyName} has no key material`);
      }

      const result = await this.keyClient.getCryptographyClient(key.name, { keyVersion: key.properties.version }).wrapKey('RSA-OAEP', dataKey);

      return {
        wrappedDataKey: result.result.toString('base64'),
        keyId: key.id!,
      };
    } catch (error) {
      throw new Error(`Failed to wrap data key: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  async unwrapDataKey(wrappedKey: WrappedKey): Promise<Buffer> {
    try {
      const keyNameFromId = this.extractKeyNameFromId(wrappedKey.keyId);
      const keyVersion = this.extractKeyVersionFromId(wrappedKey.keyId);

      const cryptoClient = this.keyClient.getCryptographyClient(keyNameFromId, { keyVersion });

      const wrappedDataKeyBuffer = Buffer.from(wrappedKey.wrappedDataKey, 'base64');
      const result = await cryptoClient.unwrapKey('RSA-OAEP', wrappedDataKeyBuffer);

      return result.result;
    } catch (error) {
      throw new Error(`Failed to unwrap data key: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  generateDataKey(): Buffer {
    return randomBytes(32); // 256-bit key for AES-256
  }

  encryptData(data: Buffer, dataKey: Buffer): { ciphertext: Buffer; iv: Buffer; authTag: Buffer } {
    const iv = randomBytes(12); // 96-bit IV for GCM
    const cipher = createCipheriv('aes-256-gcm', dataKey, iv);

    const ciphertext = Buffer.concat([cipher.update(data), cipher.final()]);
    const authTag = cipher.getAuthTag();

    return { ciphertext, iv, authTag };
  }

  decryptData(ciphertext: Buffer, dataKey: Buffer, iv: Buffer, authTag: Buffer): Buffer {
    const decipher = createDecipheriv('aes-256-gcm', dataKey, iv);
    decipher.setAuthTag(authTag);

    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  private extractKeyNameFromId(keyId: string): string {
    const parts = keyId.split('/');
    return parts[parts.length - 2];
  }

  private extractKeyVersionFromId(keyId: string): string | undefined {
    const parts = keyId.split('/');
    return parts[parts.length - 1];
  }
}
