{"file_text":"import { BlobServiceClient, ContainerClient } from '@azure/storage-blob';
import { KeyManagement, WrappedKey } from './keyManagement';

export interface UploadResult {
  blobName: string;
  keyId: string;
  wrappedDataKey: string;
}

export class BlobUploader {
  private containerClient: ContainerClient;

  constructor(
    private blobServiceClient: BlobServiceClient,
    private keyManagement: KeyManagement,
    containerName: string
  ) {
    this.containerClient = this.blobServiceClient.getContainerClient(containerName);
  }

  async ensureContainerExists(): Promise<void> {
    try {
      await this.containerClient.createIfNotExists();
    } catch (error) {
      throw new Error(`Failed to ensure container exists: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  async uploadEncrypted(blobName: string, data: string | Buffer): Promise<UploadResult> {
    try {
      await this.ensureContainerExists();

      const dataBuffer = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf8');

      const dataKey = this.keyManagement.generateDataKey();

      const { ciphertext, iv, authTag } = this.keyManagement.encryptData(dataBuffer, dataKey);

      const wrappedKey = await this.keyManagement.wrapDataKey(dataKey);

      const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);

      await blockBlobClient.upload(ciphertext, ciphertext.length, {
        metadata: {
          encryptionIV: iv.toString('base64'),
          encryptionAuthTag: authTag.toString('base64'),
          wrappedDataKey: wrappedKey.wrappedDataKey,
          keyId: wrappedKey.keyId,
          encryptionAlgorithm: 'AES-256-GCM',
        },
      });

      return {
        blobName,
        keyId: wrappedKey.keyId,
        wrappedDataKey: wrappedKey.wrappedDataKey,
      };
    } catch (error) {
      throw new Error(`Failed to upload encrypted blob: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  async downloadDecrypted(blobName: string): Promise<Buffer> {
    try {
      const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);

      const downloadResponse = await blockBlobClient.download(0);

      if (!downloadResponse.metadata) {
        throw new Error('Blob metadata is missing - cannot decrypt');
      }

      const { encryptionIV, encryptionAuthTag, wrappedDataKey, keyId } = downloadResponse.metadata;

      if (!encryptionIV || !encryptionAuthTag || !wrappedDataKey || !keyId) {
        throw new Error('Required encryption metadata is missing from blob');
      }

      const ciphertext = await this.streamToBuffer(downloadResponse.readableStreamBody!);
      const iv = Buffer.from(encryptionIV, 'base64');
      const authTag = Buffer.from(encryptionAuthTag, 'base64');

      const wrappedKeyObj: WrappedKey = {
        wrappedDataKey,
        keyId,
      };

      const dataKey = await this.keyManagement.unwrapDataKey(wrappedKeyObj);

      const plaintext = this.keyManagement.decryptData(ciphertext, dataKey, iv, authTag);

      return plaintext;
    } catch (error) {
      if (error instanceof Error && error.message.includes('BlobNotFound')) {
        throw new Error(`Blob '${blobName}' does not exist`);
      }
      throw new Error(`Failed to download and decrypt blob: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  private async streamToBuffer(readableStream: NodeJS.ReadableStream): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      readableStream.on('data', (chunk) => {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      });
      readableStream.on('end', () => {
        resolve(Buffer.concat(chunks));
      });
      readableStream.on('error', reject);
    });
  }
}
